import meta from './sprites.json'

/**
 * Sprite registry. Every image the game uses is listed in src/assets/sprites.json
 * (generated by tools/slice_sheet.py). To replace art: drop a new PNG with the same
 * key into public/assets/ and re-run the meta step — no code changes.
 */
export type SpriteKey = keyof typeof meta

export const SPRITES = meta as Record<SpriteKey, { w: number; h: number; ax: number; ay: number; ext: string }>

export function spriteUrl(key: SpriteKey) {
  return `${import.meta.env.BASE_URL}assets/${key}.${SPRITES[key].ext}`
}

/** Brand art (logo, cover) lives outside the sprite registry. */
export function brandUrl(file: 'logo.webp' | 'cover.jpg') {
  return `${import.meta.env.BASE_URL}assets/brand/${file}`
}

/** Headquarters art for each rival company (newspaper columns, rivals tab). */
export const RIVAL_ART: Record<string, SpriteKey> = {
  lotus: 'rivals/lotus-guard',
  naga: 'rivals/golden-naga',
  bluewave: 'rivals/bluewave-direct',
  summit: 'rivals/summit-general',
}

export function hasSprite(key: string): key is SpriteKey {
  return key in SPRITES
}

